// Pictures as they are edited in the spreadsheet editor: inserted from the toolbar's file
// dialog, by a paste and by a drop, selected, moved and sized with the pointer (Shift keeps the
// proportions of a corner), moved with the arrows, deleted with Delete and from their menu, saved
// and read again; refused in a read-only view and on a sheet whose objects are protected.
//
// No screenshots: the pixels of the canvas are read with getImageData(). Every picture and
// workbook is generated by code. Columns are 64 pixels wide and rows 20 high; the header is 72 by 22.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { png, pictureWorkbook } from '../test/picture-fixtures';
import { expect, test } from './helpers';

const RED = [200, 30, 30];
const BLUE = [26, 115, 232];
const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;
const MOUSE_ONLY = 'a mouse is needed';
const TOUCH_ONLY = 'a touch screen is needed';
const EMU = 9525;

/** A workbook without pictures, and the picture the tests insert: 128 by 60 pixels of one red. */
const plainBook = () => buildXlsx({ sheets: [{ name: 'Sayfa1', xml: worksheetXml('<sheetData><row r="1"><c r="A1"><v>1</v></c></row></sheetData>') }] });
const PICTURE = png(128, 60);

async function mount(page: Page, bytes: Uint8Array | number[], options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes as Uint8Array).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('#host .bym-canvas')).toBeVisible();
}

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', 'api', `return ${code}`)((window as any).__editor.view, (window as any).BymOffice), code);
const pictures = (page: Page): Promise<any[]> => view(page, 'view.pictures()') as Promise<any[]>;
const live = (page: Page) => page.locator('#host .bym-live');

/** Inserts PICTURE through the view at a cell; returns its id. */
function insert(page: Page, at: { row: number; col: number } = { row: 0, col: 0 }): Promise<number> {
  return page.evaluate(
    ({ bytes, at }) => (window as any).__editor.view.insertPicture(new Uint8Array(bytes), { at }),
    { bytes: Array.from(PICTURE), at },
  );
}

/** How many pixels of a colour a box of the canvas (CSS pixels) holds, after a forced redraw. */
function ink(page: Page, colour: number[], box: { x: number; y: number; width: number; height: number }): Promise<number> {
  return page.evaluate(
    ([colour, box]) => {
      const view = (window as any).__editor.view;
      view.render();
      const canvas = document.querySelector('#host .bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      const area = box as { x: number; y: number; width: number; height: number };
      const width = Math.max(1, Math.round(area.width * dpr));
      const height = Math.max(1, Math.round(area.height * dpr));
      const data = canvas.getContext('2d')!.getImageData(Math.round(area.x * dpr), Math.round(area.y * dpr), width, height).data;
      const [r, g, b] = colour as number[];
      let count = 0;
      for (let at = 0; at < data.length; at += 4) if (Math.abs(data[at] - r) <= 4 && Math.abs(data[at + 1] - g) <= 4 && Math.abs(data[at + 2] - b) <= 4) count++;
      return count / (dpr * dpr);
    },
    [colour, box] as [number[], typeof box],
  );
}

/** The box of the first picture on the canvas, CSS pixels, as its anchor says (no scrolling, no frozen panes). */
async function frameOf(page: Page, id = 0): Promise<{ x: number; y: number; width: number; height: number }> {
  const anchor = (await pictures(page)).find((picture) => picture.id === id).anchor;
  const x = (marker: any) => HEADER_WIDTH + marker.col * COLUMN_WIDTH + marker.colOff / EMU;
  const y = (marker: any) => HEADER_HEIGHT + marker.row * ROW_HEIGHT + marker.rowOff / EMU;
  if (anchor.kind === 'twoCell') return { x: x(anchor.from), y: y(anchor.from), width: x(anchor.to) - x(anchor.from), height: y(anchor.to) - y(anchor.from) };
  if (anchor.kind === 'oneCell') return { x: x(anchor.from), y: y(anchor.from), width: anchor.width / EMU, height: anchor.height / EMU };
  return { x: HEADER_WIDTH + anchor.x / EMU, y: HEADER_HEIGHT + anchor.y / EMU, width: anchor.width / EMU, height: anchor.height / EMU };
}

async function canvasBox(page: Page): Promise<{ x: number; y: number }> {
  const box = await page.locator('#host .bym-canvas').boundingBox();
  if (!box) throw new Error('the canvas has no box');
  return box;
}

function key(page: Page, init: KeyboardEventInit): Promise<boolean> {
  return page.evaluate((init) => {
    const event = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, ...init });
    document.querySelector('#host .bym-input')!.dispatchEvent(event);
    return event.defaultPrevented;
  }, init);
}

function touchEvent(page: Page, type: string, x: number, y: number, id = 41): Promise<void> {
  return page.evaluate(
    ([type, x, y, id]) => {
      document
        .querySelector('#host .bym-canvas')!
        .dispatchEvent(new PointerEvent(type as string, { pointerId: id as number, pointerType: 'touch', isPrimary: true, clientX: x as number, clientY: y as number, bubbles: true, cancelable: true }));
    },
    [type, x, y, id] as [string, number, number, number],
  );
}

const saved = (page: Page) => page.evaluate(async () => Array.from((await (window as any).__file.save()) as Uint8Array));

test.describe('pictures are edited', () => {
  test('a picture is inserted at the active cell, drawn, selected, saved and read again', async ({ page }) => {
    await mount(page, await plainBook());
    await view(page, 'view.select(api.parseRange("B2"))');
    const id = await page.evaluate((bytes) => (window as any).__editor.view.insertPicture(new Uint8Array(bytes)), Array.from(PICTURE));
    expect(id).toBe(0);
    await expect(live(page)).toHaveText('Picture inserted');
    expect(await view(page, 'view.selectedPicture')).toBe(0);
    const list = await pictures(page);
    expect(list.length).toBe(1);
    expect([list[0].anchor.kind, list[0].anchor.editAs, list[0].ofFile, list[0].name]).toEqual(['twoCell', 'oneCell', false, 'Picture 1']);
    expect(list[0].anchor.from).toEqual({ col: 1, colOff: 0, row: 1, rowOff: 0 });
    const frame = await frameOf(page);
    expect(Math.round(frame.width)).toBe(128);
    expect(Math.round(frame.height)).toBe(60);
    // The picture is decoded on its way: once it is there, its red fills its box.
    await expect.poll(() => ink(page, RED, { x: frame.x + 4, y: frame.y + 4, width: frame.width - 8, height: frame.height - 8 }), { timeout: 10_000 }).toBeGreaterThan(0.9 * (frame.width - 8) * (frame.height - 8));
    // Selected: a handle at its corner.
    expect(await ink(page, BLUE, { x: frame.x - 5, y: frame.y - 5, width: 10, height: 10 })).toBeGreaterThan(8);

    const bytes = await saved(page);
    await mount(page, bytes);
    const again = await pictures(page);
    expect(again.length).toBe(1);
    expect(again[0].ofFile).toBe(true);
    expect(again[0].anchor.from).toEqual({ col: 1, colOff: 0, row: 1, rowOff: 0 });
    const reopened = await frameOf(page);
    await expect.poll(() => ink(page, RED, { x: reopened.x + 4, y: reopened.y + 4, width: 20, height: 20 }), { timeout: 10_000 }).toBeGreaterThan(300);
  });

  test('the toolbar button opens the file dialog; the chosen picture is inserted, and bytes that are no picture are refused', async ({ page }) => {
    await mount(page, await plainBook());
    const button = page.locator('#host [data-command="insertPicture"]');
    await expect(button).toHaveAttribute('aria-label', 'Insert picture');
    await expect(button).toBeEnabled();
    const input = page.locator('#host .bym-tb-file');
    await expect(input).toHaveAttribute('accept', 'image/png,image/jpeg,image/gif,image/bmp');
    await input.setInputFiles({ name: 'logo.png', mimeType: 'image/png', buffer: Buffer.from(PICTURE) });
    await expect.poll(async () => (await pictures(page)).length).toBe(1);
    // The name of the file stays out of the workbook.
    expect((await pictures(page))[0].name).toBe('Picture 1');
    await input.setInputFiles({ name: 'not.png', mimeType: 'image/png', buffer: Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"/>') });
    await expect(page.locator('#host .bym-status')).toContainText('only PNG, JPEG, GIF and BMP');
    expect((await pictures(page)).length).toBe(1);
  });

  test('a picture is dragged to another place, sized by a corner with Shift in proportion, moved with the arrows and deleted', async ({ page, hasTouch }) => {
    test.skip(hasTouch, MOUSE_ONLY);
    await mount(page, await plainBook());
    await insert(page, { row: 2, col: 1 });
    await view(page, 'view.selectPicture(undefined)');
    const box = await canvasBox(page);
    let frame = await frameOf(page);
    const centre = { x: box.x + frame.x + frame.width / 2, y: box.y + frame.y + frame.height / 2 };
    await page.mouse.click(centre.x, centre.y);
    expect(await view(page, 'view.selectedPicture')).toBe(0);
    await expect(live(page)).toHaveText('Picture selected: Picture 1');

    // One column right and two rows down: the picture keeps its kind of anchor and its size.
    await page.mouse.move(centre.x, centre.y);
    await page.mouse.down();
    await page.mouse.move(centre.x + 20, centre.y + 10, { steps: 2 });
    await page.mouse.move(centre.x + COLUMN_WIDTH, centre.y + 2 * ROW_HEIGHT, { steps: 4 });
    await page.mouse.up();
    let anchor = (await pictures(page))[0].anchor;
    expect([anchor.kind, anchor.editAs, anchor.from.col, anchor.from.row]).toEqual(['twoCell', 'oneCell', 2, 4]);
    await expect(live(page)).toHaveText('Picture moved');
    frame = await frameOf(page);
    expect([Math.round(frame.width), Math.round(frame.height)]).toEqual([128, 60]);

    // The bottom right corner with Shift: the picture keeps its proportions.
    const corner = { x: box.x + frame.x + frame.width, y: box.y + frame.y + frame.height };
    await page.mouse.move(corner.x, corner.y);
    await page.keyboard.down('Shift');
    await page.mouse.down();
    await page.mouse.move(corner.x + 30, corner.y + 2, { steps: 2 });
    await page.mouse.move(corner.x + 64, corner.y + 4, { steps: 4 });
    await page.mouse.up();
    await page.keyboard.up('Shift');
    frame = await frameOf(page);
    expect(Math.abs(frame.width / frame.height - 128 / 60)).toBeLessThan(0.05);
    expect(Math.round(frame.width)).toBeGreaterThan(180);

    // The arrows move it by ten pixels, by one with Shift; Delete deletes it; undo brings it back.
    const before = await frameOf(page);
    expect(await key(page, { key: 'ArrowRight' })).toBe(true);
    expect(await key(page, { key: 'ArrowDown', shiftKey: true })).toBe(true);
    const after = await frameOf(page);
    expect(Math.round(after.x - before.x)).toBe(10);
    expect(Math.round(after.y - before.y)).toBe(1);
    await key(page, { key: 'Delete' });
    expect((await pictures(page)).length).toBe(0);
    await expect(live(page)).toHaveText('Picture deleted');
    await view(page, 'view.undo()');
    anchor = (await pictures(page))[0].anchor;
    expect(anchor.editAs).toBe('oneCell');
  });

  test('pictures of the file keep their kind of anchor when they are moved, and are deleted from their menu', async ({ page, hasTouch }) => {
    test.skip(hasTouch, MOUSE_ONLY);
    await mount(page, await pictureWorkbook());
    const list = await pictures(page);
    expect(list.map((picture) => picture.anchor.kind)).toEqual(['twoCell', 'oneCell', 'absolute']);
    for (const picture of list) {
      await view(page, `view.selectPicture(${picture.id})`);
      expect(await key(page, { key: 'ArrowDown' })).toBe(true);
    }
    expect((await pictures(page)).map((picture) => picture.anchor.kind)).toEqual(['twoCell', 'oneCell', 'absolute']);
    expect((await pictures(page))[2].anchor.y).toBe((300 + 10) * EMU);
    // The menu of the picture at its place on the sheet.
    const box = await canvasBox(page);
    const frame = await frameOf(page, 0);
    await page.mouse.click(box.x + frame.x + frame.width / 2, box.y + frame.y + frame.height / 2, { button: 'right' });
    await page.locator('#host .bym-menu').getByText('Delete picture', { exact: true }).click();
    expect((await pictures(page)).length).toBe(2);
    await expect(live(page)).toHaveText('Picture deleted');
  });

  test('a picture pasted without text, and one dropped on a cell, are inserted', async ({ page }) => {
    await mount(page, await plainBook());
    await view(page, 'view.select(api.parseRange("C3"))');
    await page.evaluate((bytes) => {
      const data = new DataTransfer();
      data.items.add(new File([new Uint8Array(bytes)], 'image.png', { type: 'image/png' }));
      const input = document.querySelector('#host .bym-input')!;
      let event: Event | undefined;
      try {
        event = new ClipboardEvent('paste', { clipboardData: data, bubbles: true, cancelable: true });
      } catch {
        event = undefined;
      }
      // Some browsers give a scripted clipboard event a clipboard of their own instead of the one passed in.
      if (!event || (event as ClipboardEvent).clipboardData !== data) {
        event = new Event('paste', { bubbles: true, cancelable: true });
        Object.defineProperty(event, 'clipboardData', { value: data });
      }
      input.dispatchEvent(event);
    }, Array.from(PICTURE));
    await expect.poll(async () => (await pictures(page)).length).toBe(1);
    expect((await pictures(page))[0].anchor.from).toEqual({ col: 2, colOff: 0, row: 2, rowOff: 0 });

    const box = await canvasBox(page);
    await page.evaluate(
      ({ bytes, x, y }) => {
        const data = new DataTransfer();
        data.items.add(new File([new Uint8Array(bytes)], 'image.png', { type: 'image/png' }));
        const canvas = document.querySelector('#host .bym-canvas')!;
        const drag = (type: string): Event => {
          const event = new DragEvent(type, { dataTransfer: data, clientX: x, clientY: y, bubbles: true, cancelable: true });
          // As for the clipboard: a browser that does not take the transfer passed in is given it.
          if (event.dataTransfer !== data) Object.defineProperty(event, 'dataTransfer', { value: data });
          return event;
        };
        const over = drag('dragover');
        canvas.dispatchEvent(over);
        if (!over.defaultPrevented) throw new Error('the drop is not taken');
        canvas.dispatchEvent(drag('drop'));
      },
      { bytes: Array.from(PICTURE), x: box.x + HEADER_WIDTH + 5 * COLUMN_WIDTH + 10, y: box.y + HEADER_HEIGHT + 10 * ROW_HEIGHT + 5 },
    );
    await expect.poll(async () => (await pictures(page)).length).toBe(2);
    expect((await pictures(page))[1].anchor.from).toEqual({ col: 5, colOff: 0, row: 10, rowOff: 0 });
  });

  test('with a finger: a tap selects the picture and a drag moves it', async ({ page, hasTouch }) => {
    test.skip(!hasTouch, TOUCH_ONLY);
    await mount(page, await plainBook());
    await insert(page, { row: 1, col: 0 });
    await view(page, 'view.selectPicture(undefined)');
    const box = await canvasBox(page);
    const frame = await frameOf(page);
    const centre = { x: box.x + frame.x + frame.width / 2, y: box.y + frame.y + frame.height / 2 };
    await touchEvent(page, 'pointerdown', centre.x, centre.y);
    await touchEvent(page, 'pointerup', centre.x, centre.y);
    expect(await view(page, 'view.selectedPicture')).toBe(0);
    await touchEvent(page, 'pointerdown', centre.x, centre.y, 42);
    await touchEvent(page, 'pointermove', centre.x + 30, centre.y + 12, 42);
    await touchEvent(page, 'pointermove', centre.x + COLUMN_WIDTH, centre.y + ROW_HEIGHT, 42);
    await touchEvent(page, 'pointerup', centre.x + COLUMN_WIDTH, centre.y + ROW_HEIGHT, 42);
    const anchor = (await pictures(page))[0].anchor;
    expect([anchor.from.col, anchor.from.row]).toEqual([1, 2]);
  });

  test('a read-only view and a sheet whose objects are protected change no picture', async ({ page, hasTouch }) => {
    await mount(page, await pictureWorkbook(), { readOnly: true });
    await expect(page.locator('#host [data-command="insertPicture"]')).toBeDisabled();
    expect(await insert(page)).toBe(-1);
    const box = await canvasBox(page);
    const frame = await frameOf(page);
    if (!hasTouch) await page.mouse.click(box.x + frame.x + frame.width / 2, box.y + frame.y + frame.height / 2);
    expect(await view(page, 'view.selectedPicture')).toBeUndefined();
    expect((await pictures(page)).length).toBe(3);
    // A file dropped on the grid is not left to the browser (which would open it in place of the page), and is not inserted.
    const prevented = await page.evaluate((bytes) => {
      const data = new DataTransfer();
      data.items.add(new File([new Uint8Array(bytes)], 'image.png', { type: 'image/png' }));
      const canvas = document.querySelector('#host .bym-canvas')!;
      const drag = (type: string): Event => {
        const event = new DragEvent(type, { dataTransfer: data, clientX: 200, clientY: 200, bubbles: true, cancelable: true });
        if (event.dataTransfer !== data) Object.defineProperty(event, 'dataTransfer', { value: data });
        canvas.dispatchEvent(event);
        return event;
      };
      return [drag('dragover').defaultPrevented, drag('drop').defaultPrevented];
    }, Array.from(PICTURE));
    expect(prevented).toEqual([true, true]);
    await expect(live(page)).toHaveText('A picture cannot be dropped here now');
    expect((await pictures(page)).length).toBe(3);

    await mount(page, await pictureWorkbook({ protection: '<sheetProtection sheet="1" objects="1"/>' }));
    expect(await view(page, 'api.picturesProblem(view.workbook, 0)')).toMatch(/protected/);
    // The button is off, and says why.
    const button = page.locator('#host [data-command="insertPicture"]');
    await expect(button).toBeDisabled();
    await expect(button).toHaveAttribute('title', 'The sheet is protected: its pictures cannot be changed');
    await expect(button).toHaveAttribute('aria-label', 'Insert picture');
    await expect(page.evaluate((bytes) => (window as any).__editor.view.insertPicture(new Uint8Array(bytes)), Array.from(PICTURE))).rejects.toThrow(/protected/);
    if (!hasTouch) await page.mouse.click(box.x + frame.x + frame.width / 2, box.y + frame.y + frame.height / 2);
    expect(await view(page, 'view.selectedPicture')).toBeUndefined();
    expect(await view(page, 'api.sheetPictures(view.workbook, 0).length')).toBe(3);
  });
});
